CREATE TABLE IF NOT EXISTS "apikey" ("id" text PRIMARY KEY NOT NULL, "config_id" text DEFAULT 'default' NOT NULL, "name" text, "start" text, "reference_id" text NOT NULL, "prefix" text, "key" text NOT NULL, "refill_interval" integer, "refill_amount" integer, "last_refill_at" timestamp, "enabled" boolean DEFAULT true, "rate_limit_enabled" boolean DEFAULT true, "rate_limit_time_window" integer, "rate_limit_max" integer, "request_count" integer, "remaining" integer, "last_request" timestamp, "expires_at" timestamp, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL, "permissions" text, "metadata" text);
CREATE INDEX IF NOT EXISTS "apikey_key_idx" ON "apikey" ("key");
CREATE INDEX IF NOT EXISTS "apikey_reference_idx" ON "apikey" ("reference_id");
